import {runActionFlow} from './approved-flow.js';
import {unmatchedReceipts,unmatchedReceiptAmount} from './receipt-matching.js';
import {esc,cash,icon,pageHead,field,row,dateLabel} from './ui.js';
import {ensurePaymentParityState,getRequestStatus,splitOutstanding} from './payments-parity-model.js';
const hub={section:'pay',page:'home'}, route=(page,more={})=>({section:'pay',page,...more});
const amount=value=>/^\d+(?:\.\d{1,2})?$/.test(String(value))?Math.round(Number(value)*100):NaN, key=prefix=>`${prefix}-${globalThis.crypto?.randomUUID?.()||Date.now()+Math.random()}`;
const button=(label,action,secondary=false)=>`<button class="button${secondary?' secondary':''}" type="button" data-parity-action="${action}">${label}</button>`;
const hidden=(ctx,n)=>ctx.state.settings.hideBalance?'••••.••':cash(n);
const label=status=>({open:'Waiting',pending:'Payment pending',paid:'Paid',cancelled:'Cancelled',declined:'Declined',expired:'Expired',settled:'All settled','refund-review':'Refund review',failed:'Declined',success:'Confirmed'})[status]||status;
const demonstration=ctx=>ctx.connected?'<p class="muted small">Shared test money · Requests and receipts sync with the signed-in accounts involved. No bank or MoMo provider is connected.</p>':'<p class="muted small">Local participant simulation. No request, payment prompt or message is sent to another person or device.</p>';
function requestPage(ctx){ensurePaymentParityState(ctx.state);const inbox=ctx.state.moneyRequests;return `<section class="page payment-parity-page">${pageHead('Requests')}<div class="content"><h1 class="large-question">Keep it clear.<br>Keep it friendly.</h1><p class="muted">A request is a nudge, never money in your balance.</p><div class="inline-actions">${button('Ask one person','request-create')}${button('Your QR code','request-qr',true)}</div><div class="section-label"><span>YOUR REQUESTS</span></div>${inbox.length?`<div class="panel">${inbox.map(r=>row({emoji:r.direction==='incoming'?'↗':'↙',title:esc(r.name),sub:`${r.direction==='incoming'?'Asked you':'You asked'} · ${esc(label(getRequestStatus(r)))}`,right:hidden(ctx,r.amount),action:`parity-request:${r.id}`})).join('')}</div>`:`<div class="empty"><h2>No awkward follow-ups.</h2><p>Your sent and received requests live here. Everyone sees a clear amount and deadline.</p></div>`}<div class="panel">${row({emoji:icon('users'),title:'Split an expense',sub:'Already paid? Give everyone their share.',action:'parity-splits'})}</div><details class="parity-demo"><summary>Try an incoming request · simulation</summary><p class="muted small">Add a sample request from Kofi. It still needs your review and authorisation.</p>${button('Add sample request','request-sample',true)}</details>${demonstration(ctx)}</div></section>`;}
function requestDetail(ctx,r){if(!r)return `<section class="page payment-parity-page">${pageHead('Request')}<p>This request is no longer available.</p>${button('All requests','requests')}</section>`;const status=getRequestStatus(r),active=status==='open';return `<section class="page payment-parity-page">${pageHead('Request')}<div class="content"><span class="eyebrow">${r.direction==='incoming'?'FROM':'YOU ASKED'} ${esc(r.name.toUpperCase())}</span><h1 class="amount amount-xl">${hidden(ctx,r.amount)}</h1><span class="chip selected">${esc(label(status))}</span><p>${esc(r.note||'Money between friends, kept clear.')}</p><div class="panel">${row({title:'Expires',right:dateLabel(r.expiresAt)})}${row({title:'Reference',sub:esc(r.id)})}${r.paymentId?row({title:'Linked payment',sub:'Only a confirmed ledger result marks this paid.',action:'parity-request-payment'}):''}</div>${active&&r.direction==='incoming'?button('Review payment','request-pay'):''}${active?button(r.direction==='incoming'?'Decline request':'Cancel request',r.direction==='incoming'?'request-decline':'request-cancel',true):''}${button('Report this request','request-report',true)}${active&&r.direction==='outgoing'&&!ctx.connected?`<details class="parity-demo"><summary>Participant simulation</summary><p class="muted small">Confirm money received from ${esc(r.name)}. A chat claim alone would never do this.</p>${button('Simulate confirmed receipt','request-receive',true)}</details>`:''}${ctx.connected&&active&&r.direction==='outgoing'?'<div class="notice"><span>This request is in their signed-in Lumo account. Ask them to open Payments → Requests and review the amount and reference. Your personal receiving QR does not carry this request.</span></div>':''}${r.history?.length?`<div class="section-label"><span>REQUEST HISTORY</span></div><div class="panel">${r.history.map(e=>row({title:esc(e.type.replaceAll('-',' ')),sub:dateLabel(e.at)})).join('')}</div>`:''}${demonstration(ctx)}</div></section>`;}
function splitPage(ctx){ensurePaymentParityState(ctx.state);return `<section class="page payment-parity-page">${pageHead('Expense splits')}<div class="content"><h1 class="large-question">One person paid.<br>Everyone’s in.</h1><p class="muted">Lunch, a ride, project supplies. Split an expense you already paid.</p>${button('Split an expense','split-create')}<div class="section-label"><span>YOUR SPLITS</span></div>${ctx.state.expenseSplits.length?`<div class="panel">${ctx.state.expenseSplits.map(s=>row({emoji:icon('users'),title:esc(s.purpose),sub:`${s.members.length} people · ${esc(label(s.status))}`,right:hidden(ctx,splitOutstanding(s)),action:`parity-split:${s.id}`})).join('')}</div>`:'<div class="empty"><h2>Good friends. Clear shares.</h2><p>Unpaid shares stay outside your available money.</p></div>'}${demonstration(ctx)}</div></section>`;}
function splitDetail(ctx,s){if(!s)return `<section class="page payment-parity-page">${pageHead('Expense split')}<p>Split not found.</p></section>`;return `<section class="page payment-parity-page">${pageHead('Expense split')}<div class="content"><h1>${esc(s.purpose)}</h1><p class="amount amount-xl">${hidden(ctx,s.amount)}</p>${s.status==='refund-review'?'<div class="notice"><span>The original payment was reversed. New share collections are stopped. Confirmed repayments remain in history; review any money to return with your friends.</span></div>':''}<p class="muted">${hidden(ctx,splitOutstanding(s))} still expected · ${s.mode==='custom'?'Custom shares':'Split equally'}</p>${s.transactionId?button('View original payment','split-original',true):'<p class="muted small">Expense already paid outside Lumo. Creating this split does not debit Everyday.</p>'}<div class="panel">${s.members.map(m=>`<div class="row"><span class="row-icon">${esc(m.name[0])}</span><span class="row-copy"><span class="row-title">${esc(m.isMe?'You':m.name)}</span><span class="row-sub">${m.isMe?'Your share':m.paid>=m.amount?'Received':`${hidden(ctx,m.amount-m.paid)} outstanding`}</span></span><strong>${hidden(ctx,m.amount)}</strong>${!m.isMe&&m.paid<m.amount&&s.status==='open'?`<button class="text-button" data-parity-member="${esc(m.id)}">Record receipt</button>`:''}</div>`).join('')}</div>${s.status==='open'?button('Cancel outstanding requests','split-cancel',true):''}<p class="muted small">Record receipt only after money has arrived. Cash and other-bank repayments never increase your Lumo balance.</p>${demonstration(ctx)}</div></section>`;}
function fundingPage(ctx,route){ensurePaymentParityState(ctx.state);const f=ctx.state.fundingAttempts.find(x=>x.id===route.id);if(!f)return `<section class="page payment-parity-page">${pageHead('Your top-ups')}<div class="content"><h1>Fuel for your plans.</h1>${ctx.state.fundingAttempts.length?`<div class="panel">${ctx.state.fundingAttempts.map(f=>row({emoji:icon(f.rail==='bank'?'bank':'phone'),title:esc(f.source),sub:`${label(f.status)} · ${dateLabel(f.createdAt)}`,right:hidden(ctx,f.amount),action:`parity-funding:${f.id}`})).join('')}</div>`:'<p class="muted">Your top-up references will appear here.</p>'}${button('Add money','fund-new')}${demonstration(ctx)}</div></section>`;return `<section class="page payment-parity-page payment-status">${pageHead('Add money')}<div class="content"><div class="status-orbit">${icon(f.status==='success'?'check':f.status==='pending'?'clock':'info',40)}</div><h1>${f.status==='success'?'Money’s here.':f.status==='pending'?'One more little step.':'That top-up didn’t land.'}</h1><p class="amount amount-xl">${hidden(ctx,f.amount)}</p><p class="muted">${f.status==='pending'?(f.rail==='momo'?'Waiting for approval in your own mobile-money wallet.':'Waiting for your bank transfer to arrive.'):'Only confirmed funding increases Everyday.'}</p><div class="panel">${row({title:'From',right:esc(f.source)})}${f.number?row({title:'Your number',right:esc(f.number)}):''}${row({title:'Status',right:esc(label(f.status))})}${row({title:'Reference',sub:esc(f.reference)})}</div>${f.status==='pending'?button('Check this reference','fund-check',true):''}${['failed','expired'].includes(f.status)?button('Review and try again','fund-retry'):''}${f.status==='success'?button('Back to your money','fund-return'):''}${button('Missing a top-up?','fund-help',true)}${f.status==='pending'?`<details class="parity-demo"><summary>Funding simulation</summary><p class="muted small">Choose the provider’s result. Checking alone never confirms it.</p>${button('Confirm funding','fund-success',true)}${button('Decline funding','fund-failed',true)}${button('Expire funding','fund-expired',true)}</details>`:''}${demonstration(ctx)}</div></section>`;}
export function renderPaymentParity(ctx,r){if(r.page==='requests')return requestPage(ctx);if(r.page==='request-detail')return requestDetail(ctx,ctx.state.moneyRequests?.find(x=>x.id===r.id));if(r.page==='splits')return splitPage(ctx);if(r.page==='split-detail')return splitDetail(ctx,ctx.state.expenseSplits?.find(x=>x.id===r.id));if(r.page==='funding-detail')return fundingPage(ctx,r);return '';}
function finish(ctx,result,destination){if(!result?.ok){ctx.toast(result?.message||'Check those details.');return false;}ctx.closeSheet();if(destination)ctx.go(destination);else ctx.refresh();ctx.toast(result.message);return true;}
export function createRequestSheet(ctx,{incoming=false,name=''}={}){if(ctx.connected&&incoming){ctx.toast('Sample incoming requests are only available in the sample experience.');return;}ctx.sheet(`<h2>${incoming?'Try a request from a friend.':'Who’s paying you back?'}</h2><form class="form-stack" novalidate>${field({label:incoming?'Sample sender':'Their name',name:'name',value:name,placeholder:'e.g. Kofi'})}${field({label:'Amount (GH₵)',name:'amount',type:'number',min:'0.01',placeholder:'e.g. 30'})}${field({label:'What’s it for?',name:'note',placeholder:'Our project printing'})}<p class="muted small">Fixed amount. Expires in seven days. You can cancel an unpaid request.${ctx.connected?' They can review it in Payments → Requests in their signed-in Lumo account.':''}</p><p class="error" role="alert"></p><button class="button" type="submit">${incoming?'Add sample request':'Create request'}</button></form>`,el=>{const form=el.querySelector('form'),actionKey=key('request');if(ctx.connected)form.elements.name.placeholder='Lumo username or registered phone';form.onsubmit=e=>{return runActionFlow(function*(){e.preventDefault();const result=(yield (ctx.actAsync||ctx.act).call(ctx,incoming?'simulateIncomingRequest':'createMoneyRequest',{name:form.elements.name.value,amount:amount(form.elements.amount.value),note:form.elements.note.value,idempotencyKey:actionKey}));if(!result.ok){form.querySelector('.error').textContent=result.message;return;}finish(ctx,result,route('request-detail',{id:result.id,backTo:route('requests')}));});};});}
export function createSplitSheet(ctx,{transactionId}={}){const original=ctx.state.transactions.find(t=>t.id===transactionId),values=ctx.draft.expenseSplit||{purpose:original?.merchant||'',amount:original?(original.amount/100).toFixed(2):'',names:'',mode:'equal'};ctx.sheet(`<h2>Who’s in on this?</h2><p>${original?'Split this confirmed payment.':'Use an expense you have already paid. No new payment is made.'}</p><form class="form-stack" novalidate>${field({label:'What did you pay for?',name:'purpose',value:values.purpose,placeholder:'Project printing'})}${field({label:'Total paid (GH₵)',name:'amount',type:'number',min:'0.01',value:values.amount})}<label class="field"><span>Friends, one name per line</span><textarea class="input" name="names" rows="3" placeholder="Kofi\nAkosua">${esc(values.names)}</textarea></label><p class="muted small">You are included automatically. Add up to eight friends.</p><label class="field"><span>How shall we split it?</span><select class="input" name="mode"><option value="equal">Equally</option><option value="custom" ${values.mode==='custom'?'selected':''}>Choose each share</option></select></label><p class="error" role="alert"></p><button class="button" type="submit">Review shares</button></form>`,el=>{const form=el.querySelector('form');if(ctx.connected)form.elements.names.placeholder='Lumo usernames or registered phones, one per line';if(original)form.elements.amount.readOnly=true;form.onsubmit=e=>{e.preventDefault();const names=form.elements.names.value.split(/\n|,/).map(n=>n.trim()).filter(Boolean),total=original?.amount||amount(form.elements.amount.value);if(names.length<1||names.length>8||!Number.isSafeInteger(total)||total<=0){form.querySelector('.error').textContent='Add 1–8 friends and a valid total.';return;}ctx.draft.expenseSplit={purpose:form.elements.purpose.value,amount:form.elements.amount.value,names:form.elements.names.value,mode:form.elements.mode.value};const members=[{name:'You',isMe:true},...names.map(name=>({name,isMe:false}))],base=Math.floor(total/members.length);members.forEach((m,i)=>m.amount=base+(i<total%members.length?1:0));reviewSplitSheet(ctx,{amount:total,purpose:form.elements.purpose.value,mode:form.elements.mode.value,transactionId,members});};});}
function reviewSplitSheet(ctx,payload){ctx.sheet(`<h2>Everyone’s share.</h2><p>${cash(payload.amount)} for ${esc(payload.purpose||'your shared expense')}.</p><form class="form-stack" novalidate>${payload.members.map((m,i)=>field({label:m.isMe?'Your share':m.name,name:`share${i}`,type:'number',value:(m.amount/100).toFixed(2),min:'0.01'})).join('')}<p class="muted small">${payload.mode==='equal'?'Pesewas are shared evenly.':'Custom shares must add up to the original expense.'} Unpaid shares stay outside your available balance.</p><p class="error" role="alert"></p><button class="button" type="submit">Create split</button></form>`,el=>{const form=el.querySelector('form'),actionKey=key('split');if(payload.mode==='equal')form.querySelectorAll('input').forEach(input=>input.readOnly=true);form.onsubmit=e=>{return runActionFlow(function*(){e.preventDefault();const result=(yield (ctx.actAsync||ctx.act).call(ctx,'createExpenseSplit',{...payload,members:payload.members.map((m,i)=>({...m,amount:amount(form.elements[`share${i}`].value)})),idempotencyKey:actionKey}));if(!result.ok){form.querySelector('.error').textContent=result.message;return;}delete ctx.draft.expenseSplit;finish(ctx,result,route('split-detail',{id:result.id,backTo:route('splits')}));});};});}
export function bindPaymentParity(ctx,r){const root=ctx.$('.payment-parity-page');if(!root)return()=>{};let alive=true;const refreshAction=(type,p={},auth=false)=>{return runActionFlow(function*(){const apply=()=>{return runActionFlow(function*(){if(!alive||!root.isConnected)return;const result=(yield (ctx.actAsync||ctx.act).call(ctx,type,{...p,idempotencyKey:key(type)}));finish(ctx,result);});};auth?ctx.auth({title:'Confirm this demo money move.',onSuccess:apply}):(yield apply());});};const onClick=e=>{return runActionFlow(function*(){if(!alive||!root.isConnected)return;const b=e.target.closest('button');if(!b||b.disabled)return;const a=b.dataset.parityAction||b.dataset.action||'';
if(a.startsWith('parity-request:'))return ctx.go(route('request-detail',{id:a.slice(15),backTo:r}));if(a.startsWith('parity-split:'))return ctx.go(route('split-detail',{id:a.slice(13),backTo:r}));if(a.startsWith('parity-funding:'))return ctx.go(route('funding-detail',{id:a.slice(15),backTo:r}));if(a==='request-create')return createRequestSheet(ctx);if(a==='request-sample')return createRequestSheet(ctx,{incoming:true,name:'Kofi Mensah'});if(a==='request-qr')return ctx.go(route('collect',{backTo:r}));if(a==='requests')return ctx.go(route('requests'));if(a==='parity-splits')return ctx.go(route('splits',{backTo:r}));if(a==='split-create')return createSplitSheet(ctx);if(a==='fund-new')return ctx.openFunding?.();
const request=ctx.state.moneyRequests?.find(x=>x.id===r.id),split=ctx.state.expenseSplits?.find(x=>x.id===r.id),funding=ctx.state.fundingAttempts?.find(x=>x.id===r.id);
if(a==='request-pay'&&request){if(ctx.canStartPayment?.()===false)return;if(getRequestStatus(request)!=='open')return ctx.toast('This request is no longer open.');ctx.draft.payment={rail:'lumo',recipient:{name:request.name,emoji:request.name[0]},amount:request.amount,amountText:(request.amount/100).toFixed(2),category:'Other',note:request.note,requestId:request.id,idempotencyKey:key('request-payment'),flowOrigin:{...r}};ctx.saveDraft?.();return ctx.go(route('review',{backTo:r}));}
if(a==='parity-request-payment'&&request?.paymentId)return ctx.go(route('transaction',{id:request.paymentId,backTo:r,returnTo:r}));if(a==='request-cancel')return (yield refreshAction('cancelMoneyRequest',{id:r.id}));if(a==='request-decline')return (yield refreshAction('declineMoneyRequest',{id:r.id}));if(a==='request-report')return (yield refreshAction('reportMoneyRequest',{id:r.id}));if(a==='request-receive')return (yield refreshAction('confirmRequestedMoney',{id:r.id},true));
if(a==='split-original'&&split?.transactionId)return ctx.go(route('transaction',{id:split.transactionId,backTo:r,returnTo:r}));if(a==='split-cancel')return (yield refreshAction('cancelExpenseSplit',{id:r.id}));if(b.dataset.parityMember&&split){const member=split.members.find(m=>m.id===b.dataset.parityMember);if(!member)return;const actionKey=key('share');return ctx.sheet(`<h2>How did ${esc(member.name)} pay?</h2><p>Record only what has arrived. This is a labelled local simulation.</p><form class="form-stack">${field({label:'Amount received (GH₵)',name:'amount',type:'number',min:'0.01',value:((member.amount-member.paid)/100).toFixed(2)})}<label class="field"><span>Received into</span><select class="input" name="method"><option value="lumo">Lumo · simulate confirmed transfer</option><option value="cash">Cash · record only</option><option value="other">Another bank or MoMo · record only</option></select></label><p class="error" role="alert"></p><button class="button" type="submit">Review receipt</button></form>`,el=>{const form=el.querySelector('form');if(ctx.connected)attachSharedReceiptChoice(ctx,form);form.onsubmit=e=>{e.preventDefault();if(ctx.connected&&form.elements.method.value==='lumo'){const tx=ctx.state.transactions?.find(t=>t.id===form.elements.receiptTransaction?.value),available=unmatchedReceiptAmount(tx,{requireLedger:true});if(!available){form.querySelector('.error').textContent='Choose a confirmed Lumo receipt with unmatched money before matching this share.';return;}if(amount(form.elements.amount.value)>available){form.querySelector('.error').textContent=`This receipt has ${cash(available)} unmatched. Choose that amount or less.`;return;}}const payload={splitId:split.id,memberId:member.id,amount:amount(form.elements.amount.value),method:form.elements.method.value,...(ctx.connected&&form.elements.method.value==='lumo'?{receiptTransactionId:form.elements.receiptTransaction.value}:{}),idempotencyKey:actionKey};ctx.auth({title:'Confirm received share?',onSuccess:()=>{return runActionFlow(function*(){const result=(yield (ctx.actAsync||ctx.act).call(ctx,'settleSplitShare',payload));finish(ctx,result);});}});};});}
if(a==='fund-check')return (yield refreshAction('checkFundingAttempt',{id:r.id}));if(a==='fund-retry'&&funding){return ctx.auth({title:`Try ${cash(funding.amount)} from ${funding.rail==='bank'?'your bank':funding.number} again?`,onSuccess:()=>{return runActionFlow(function*(){if(!alive||!root.isConnected)return;const result=(yield (ctx.actAsync||ctx.act).call(ctx,'retryFundingAttempt',{id:r.id,idempotencyKey:key('fund-retry')}));if(result.ok)return ctx.go(route('funding-detail',{id:result.id,backTo:r.backTo||hub}));ctx.toast(result.message);});}});}
if(['fund-success','fund-failed','fund-expired'].includes(a))return (yield refreshAction('resolveFundingAttempt',{id:r.id,status:a.slice(5)},a==='fund-success'));if(a==='fund-return')return ctx.go(ctx.draft.fundingReturnTo||{section:'home',page:'home'});if(a==='fund-help')return ctx.go({section:'life',page:'account-support-new',fundingId:funding?.id,returnTo:r});});};root.addEventListener('click',onClick);return()=>{alive=false;root.removeEventListener('click',onClick);};}

function attachSharedReceiptChoice(ctx,form){
 const receipts=unmatchedReceipts(ctx.state.transactions,{requireLedger:true});
 const label=form.ownerDocument.createElement('label');label.className='field';
 label.innerHTML=`<span>Confirmed Lumo receipt</span><select class="input" name="receiptTransaction"><option value="">Choose money already received</option>${receipts.map(tx=>`<option value="${esc(tx.id)}">${esc(tx.merchant)} · ${cash(unmatchedReceiptAmount(tx,{requireLedger:true}))} unmatched · ${esc(dateLabel(tx.at))}</option>`).join('')}</select>`;
 form.querySelector('.error').before(label);
 const method=form.elements.method;method.querySelector('[value="lumo"]').textContent='Lumo · match a confirmed receipt';
 const sync=()=>{label.hidden=method.value!=='lumo';};method.addEventListener('change',sync);sync();
}
